window.AUTH=window.AUTH||{};window.AUTH["23-1324"]={"d":"23-1324","id":"2024/23-1324","n":"Perttu v. Richards","briefs":[{"k":"petitioner","label":"Brief of petitioner Thomas Perttu","date":"2024-12-02","url":"https://www.supremecourt.gov/DocketPDF/23/23-1324/333054/20241202140337368_23-1324%20Richards%20Merits%20A.pdf","side":"pet","n":91},{"k":"respondent","label":"Brief of respondent Kyle Richards","date":"2025-01-14","url":"https://www.supremecourt.gov/DocketPDF/23/23-1324/337290/20250114171705639_23-1324%20Richards%20Merits%20Brief%20-%20Final.pdf","side":"res","n":66},{"k":"reply","label":"Reply of petitioner Thomas Perttu","date":"2025-02-13","url":"https://www.supremecourt.gov/DocketPDF/23/23-1324/342741/20250213165307092_23-1324%20Richards%20Reply%202-13-2025%2010%20AM.pdf","side":"pet","n":51}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/605us2r47_bqm2.pdf","tr":true,"items":[{"t":"case","label":"Albino v. Baca","cite":"747 F.3d 1162","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/747/1162/","op":4,"by":{"0":"12, 16","1":"23"}},{"t":"case","label":"Alexander v. Hawk","cite":"159 F.3d 1321","y":1998,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/159/1321/","by":{"0":"5, 35, 37"}},{"t":"case","label":"Altschul v. Gittings","cite":"86 F. 200","y":1898,"court":"C.C.D. Ore.","url":"https://www.courtlistener.com/c/F./86/200/","by":{"0":"24, 27","1":"44"}},{"t":"case","label":"Am. Heritage Life Ins. Co. v. Orr","cite":"294 F.3d 702","y":2002,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/294/702/","by":{"0":"18, 42","2":"3"}},{"t":"case","label":"Atlas Roofing Co. v. Occupational Safety & Health Review Comm’n","cite":"430 U.S. 442","y":1977,"id":"1976/75-746","sc":1,"sum":"The Seventh Amendment does not prevent Congress from assigning to an administrative agency the task of adjudicating violations of OSHA. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17","2":"6"}},{"t":"case","label":"Baltimore & Carolina Line, Inc. v. Redman","cite":"295 U.S. 654","y":1935,"id":"scdb/1934-135","sc":1,"sum":"that in reversing because as a matter of law the evidence was insufficient to sustain the -Tekdict, the judgment of the Circuit Court of Appeals should embody a direction for a judgment of dismissal on the merits, and not for a new trial; and that such judgment of dismissal would be thp equivalent of a judgment for the defendant on a verdict directed in its favor.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 21","1":"31, 32"}},{"t":"case","label":"Beacon Theatres, Inc. v. Westover","cite":"359 U.S. 500","y":1959,"id":"1958/45","sc":1,"op":36,"ar":15,"sum":"Recognizing that Beacon Theatres establishes a “general prudential rule”.","sumSrc":"opinion","by":{"0":"15, 38, 39, 40, 43","1":"28, 29, 45, 46","2":"13"}},{"t":"case","label":"Bethea v. Crouse","cite":"417 F.2d 504","y":1969,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/417/504/","by":{"0":"21"}},{"t":"case","label":"Booth v. Churner","cite":"532 U.S. 731","y":2001,"id":"2000/99-1964","sc":1,"sum":"The Court held that even though the prison grievance procedure did not provide for requested monetary relief, Booth was nonetheless required to exhaust administrative remedies before filing suit with respect to prison conditions.","sumSrc":"Oyez","by":{"0":"5, 35","2":"5, 11"}},{"t":"case","label":"Bowles v. Wilke","cite":"175 F.2d 35","y":1949,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/175/35/","by":{"0":"19"}},{"t":"case","label":"Brown v. Drain","cite":"112 F. 582","y":1901,"court":"C.C.S.D. Cal.","url":"https://www.courtlistener.com/c/F./112/582/","by":{"0":"24"}},{"t":"case","label":"Brown, Bonnell & Co. v. Lake Superior Iron Co.","cite":"134 U.S. 530","y":1890,"id":"scdb/1889-195","sc":1,"sum":"Explaining that the adequate remedy at law objection “should be taken at the earliest opportunity”.","sumSrc":"brief:0","by":{"0":"30"}},{"t":"case","label":"Bryant v. Rich","cite":"530 F.3d 1368","y":2008,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/530/1368/","op":1,"by":{"0":"16, 19","1":"22, 38, 39"}},{"t":"case","label":"Burford v. Sun Oil Co.","cite":"319 U.S. 315","y":1943,"id":"scdb/1942-038","sc":1,"by":{"0":"31"}},{"t":"case","label":"Caley v. Gulfstream Aerospace Corp.","cite":"428 F.3d 1359","y":2005,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/428/1359/","by":{"0":"18, 42","2":"3"}},{"t":"case","label":"City of Monterey v. Del Monte Dunes at Monterey, Ltd.","cite":"526 U.S. 687","y":1999,"id":"1998/97-1235","sc":1,"op":9,"sum":"Holding that “a § 1983 suit seeking legal relief is an action at law within the meaning of the Seventh Amendment” and that a “predominantly factual question” in such an action is “for the jury”.","sumSrc":"opinion","by":{"0":"21, 22, 35, 36","1":"9, 31-34, 43, 48","2":"18, 19, 22"}},{"t":"case","label":"Colgrove v. Battin","cite":"413 U.S. 149","y":1973,"id":"1972/71-1442","sc":1,"sum":"Local federal court rule providing that a jury for the trial of civil cases shall consist of six persons comports with the Seventh Amendment requirement and the coextensive statutory requirement of 28 U. S. C. § 2072 that the right of trial by jury be preserved in suits at common law, and is not inconsistent with Fed. Rule Civ. Proc. 48 that deals only with parties' stipulations regarding jury size. Pp. 151-164. 456 …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14, 21, 45"}},{"t":"case","label":"Dairy Queen, Inc. v. Wood","cite":"369 U.S. 469","y":1962,"id":"1961/244","sc":1,"op":2,"sum":"The District Judge erred in refusing petitioner's.demand for a trial by jury of the factual issues related to the question whether there had been a breach of contract or a trademark infringement, and the Court of Appeals should have corrected that error by granting the petition for mandamus.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38, 40, 43","1":"3, 14, 26","2":"13"}},{"t":"case","label":"Danjaq LLC v. Sony Corp.","cite":"263 F.3d 942","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/263/942/","by":{"0":"37"}},{"t":"case","label":"Dillon v. Rogers","cite":"596 F.3d 260","y":2010,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/596/260/","op":1,"by":{"0":"16","1":"22"}},{"t":"case","label":"Dimick v. Schiedt","cite":"293 U.S. 474","y":1935,"id":"scdb/1934-155","sc":1,"op":1,"sum":"1. Under the Seventh Amendment, a federal court, finding a verdict inadequate, is without power to add to it by refusing to grant the plaintiff a new trial if the defendant will accept an increase which the court deems sufficient. So held in an action for personal injuries due to negligence.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 20","1":"1, 14"}},{"t":"case","label":"Dundee Mortgage Trust Invest Co. v. Charlton","cite":"32 F. 192","y":1887,"court":"C.C.D. Ore.","url":"https://www.courtlistener.com/c/F./32/192/","by":{"0":"23, 24, 27","1":"44"}},{"t":"case","label":"Duvall v. Att’y Gen. of the United States","cite":"436 F.3d 382","y":2006,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/436/382/","by":{"0":"44"}},{"t":"case","label":"Fireman’s Fund Insurance Co. v. Railway Express Agency, Inc.","cite":"253 F.2d 780","y":1958,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/253/780/","op":1,"by":{"0":"12, 13, 44","1":"9","2":"10"}},{"t":"case","label":"Galloway v. United States","cite":"319 U.S. 372","y":1943,"id":"scdb/1942-050","sc":1,"sum":"1. In this suit against the United States to recover benefits under a contract of war risk insurance, on account of alleged total and permanent disability resulting from insanity of the insured while the policy was in force, held that the evidence was insufficient to support a judgment for the plaintiff and the trial court properly granted the Government's motion for a directed verdict.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17","2":"22"}},{"t":"case","label":"Gasoline Products Co. v. Champlin Refining Co.","cite":"283 U.S. 494","y":1943,"id":"scdb/1930-068","sc":1,"sum":"that in reversing the judgment as to the counterclaim and directing a new trial with respect to the amount of damages because of error in the instructions concerning the measure of damages under it, it was not necessary to disturb the judgment on the main cause of action; but there should be a retrial of all the issues raised by the counterclaim, be-","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Gorham Mfg. Co. v. State Tax Comm’n of N.Y.","cite":"266 U.S. 265","y":1924,"id":"scdb/1924-006","sc":1,"sum":"1. A taxpayer who has not exhausted the remedy provided before an administrative board to secure the correct assessment of a tax, will not be heard to assert its invalidity in a suit to enjoin its collection.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Granfinanciera, S.A. v. Nordberg","cite":"492 U.S. 33","y":1989,"id":"1988/87-1716","sc":1,"ar":1,"sum":"The Court held that the Seventh Amendment protected the right to a trial by jury in all cases in which a legal right, as opposed to an equitable right, was at issue.","sumSrc":"Oyez","by":{"0":"20, 47","1":"30"}},{"t":"case","label":"Granite State Ins. Co. v. Smart Modular Techs.","cite":"76 F.3d 1023","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/76/1023/","by":{"0":"33"}},{"t":"case","label":"Great Lakes Co. v. Huffman","cite":"319 U.S. 293","y":1943,"id":"scdb/1942-144","sc":1,"by":{"0":"30"}},{"t":"case","label":"Gulf Oil Corp. v. Gilbert","cite":"330 U.S. 501","y":1947,"id":"scdb/1946-068","sc":1,"op":1,"sum":"It did not abuse its discretion in doing so.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Herbert v. Lando","cite":"441 U.S. 153","y":1979,"id":"1978/77-1105","sc":1,"sum":"The Court reversed the decision of the Court of Appeals and held that the privilege not to answer editorial inquiries is not absolute. Justice White argued that shielding editorial decision-making from inquiry would \"substantially enhance the burden of proving actual malice,\" a burden which was already substantial in the Court's view.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Hyman v. City of Gastonia","cite":"466 F.3d 284","y":2006,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/466/284/","by":{"0":"19"}},{"t":"case","label":"Island Creek Coal Co. v. Bryan","cite":"937 F.3d 738","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/937/738/","sum":"Noting that “the exhaustion ‘doctrine had its origin in a discretionary rule adopted by courts of equity to the effect that a petitioner will be denied equitable relief when he has failed to pursue an available administrative remedy by which he might obtain the same relief.’ ”.","sumSrc":"brief:0","by":{"0":"28"}},{"t":"case","label":"Katchen v. Landy","cite":"382 U.S. 323","y":1966,"id":"1965/28","sc":1,"op":6,"ar":1,"sum":"A bankruptcy court has summary jurisdiction to order the surrender of voidable preferences asserted and proved by the trustee in response to a claim filed by the creditor who received the preferences.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38, 46, 47","1":"29"}},{"t":"case","label":"Koster v. Am. Lumbermens Mut. Cas. Co.","cite":"330 U.S. 518","y":1947,"id":"scdb/1946-069","sc":1,"op":1,"by":{"0":"30"}},{"t":"case","label":"Lee v. Willey","cite":"789 F.3d 673","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/789/673/","op":5,"by":{"0":"11, 16","1":"22"}},{"t":"case","label":"Liberty Oil Co. v. Condon Nat’l Bank","cite":"260 U.S. 235","y":1922,"id":"scdb/1922-035","sc":1,"op":2,"sum":"1. Where a defendant, suedat law in the District Court for money had and received, avers by answer and.cross-petition that it is a stakeholder of the money in question, offers to pay it into court,\" and prays that the other claimants be made parties, that the issue be litigated between them and the plaintiff, and that the defendant be dischárged' from liability, the proceeding becomes an equitable one, an …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"33, 34, 41","1":"2, 13, 45, 47"}},{"t":"case","label":"Markman v. Westview Instruments, Inc.","cite":"517 U.S. 370","y":1996,"id":"1995/95-26","sc":1,"op":2,"ar":1,"sum":"Authored by Justice David H. Souter, the Court held that the construction of a patent, including terms of art within its claim, is exclusively within the province of the court. Justice Souter wrote that \"judges, not juries, are the better suited to find the acquired meaning of patent terms.\".","sumSrc":"Oyez","by":{"0":"40, 43","1":"9, 32, 33, 43","2":"9, 19, 20, 22"}},{"t":"case","label":"McCarthy v. Madigan","cite":"503 U.S. 140","y":1992,"id":"1991/90-6861","sc":1,"sum":"Exhaustion of the Bureau of Prisons' administrative procedure is not required before a federal prisoner can initiate a Bivens action solely for money damages.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28, 29, 31, 36, 42"}},{"t":"case","label":"Messa v. Goord","cite":"652 F.3d 305","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/652/305/","op":1,"sum":"Explaining that the doctrines of exhaustion and statutes of limitations “play . . . important—and distinct—roles in our system of justice”.","sumSrc":"brief:0","by":{"0":"16, 45","1":"22, 26"}},{"t":"case","label":"Morales v. Trans World Airlines, Inc.","cite":"504 U.S. 374","y":1992,"id":"1991/90-1604","sc":1,"sum":"The Court held that the Airline Deregulation Act of 1978 prevents states from prohibiting deceptive airline fare advertisements through enforcement of their general consumer protection statuses.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Myers v. Bethlehem Shipbuilding Co.","cite":"303 U.S. 41","y":1938,"id":"scdb/1937-127","sc":1,"sum":"(1) That the District Court had no jurisdiction of a suit by the corpdration to enjoin the Board from holding the hearing. P.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26","1":"2, 38, 44"}},{"t":"case","label":"Natural Gas Pipeline Co. v. Slattery","cite":"302 U.S. 300","y":1937,"id":"scdb/1937-009","sc":1,"sum":"1. A Delaware corporation, engaged in piping and selling natural gas in interstate commerce, sold and delivered gas in Illinois, under a long term contract, to an Illinois corporation which, in turn, sold it in that State to distributing companies. All the stock of this local gas company and many of the outstanding shares of the pipeline company were owned by a local investment company. Two of the eight or nine …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 27, 29"}},{"t":"case","label":"O’Sullivan v. Boerckel","cite":"526 U.S. 838","y":1999,"id":"1998/97-2048","sc":1,"op":5,"sum":"Delivered by Justice Sandra Day O'Connor, the Court held that in order to satisfy the exhaustion requirement, a state prisoner must present his claims to a state supreme court in a petition for discretionary review when that review is part of the State's ordinary appellate review procedure.","sumSrc":"Oyez","by":{"0":"32, 33"}},{"t":"case","label":"Ohio Bureau of Emp. Servs. v. Hodory","cite":"431 U.S. 471","y":1977,"id":"1976/75-1707","sc":1,"ar":1,"sum":"Appellee, an employee of United States Steel Corporation (USS) at a plant in Ohio, was furloughed when the plant was shut down because of a reduction in fuel supply resulting from a nationwide strike of workers at USS's coal mines. Appellee applied to appellant Ohio Bureau of Employment Services for unemployment benefits but his claim was disallowed under an Ohio statute that disqualified a worker from such benefits …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Parklane Hosiery Co. v. Shore","cite":"439 U.S. 322","y":1979,"id":"1978/77-1305","sc":1,"op":7,"ar":1,"sum":"Respondent brought this stockholder's class action in the District Court for damages and other relief against petitioners, a corporation, its officers, directors, and stockholders, who allegedly had issued a materially false and misleading proxy statement in violation of the federal securities laws and Securities and Exchange Commission (SEC) regulations. Before the action came to trial the SEC sued the same …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 38, 40, 44","2":"12, 17"}},{"t":"case","label":"Parsons v. Bedford, Breedlove & Robeson","cite":"28 U.S. 433","y":1830,"id":"scdb/1830-014","sc":1,"sum":"This action was instituted in the district court of the United Slates for the eastern district of Louisiana,- according to the forms of proceedings adopted and practised in the courfs of that state. The cause was tried by.a special jury, and a verdict was rendered for the plaintiff. On the trial, the' counsel for the defendant moved the court ‘to direct the clerk of the court to take dojvn in writing the testimony …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Pavey v. Conley","cite":"544 F.3d 739","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/544/739/","op":5,"sum":"Explaining that “in many cases the only consequence of a failure to exhaust is that the prisoner must go back to the bottom rung of the administrative ladder”.","sumSrc":"brief:0","by":{"0":"44, 45","2":"4, 17"}},{"t":"case","label":"Perez v. Wis. Dep’t of Corr.","cite":"182 F.3d 532","y":1999,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/182/532/","sum":"Explaining that exhaustion is “designed to prevent [a] decision on the merits”.","sumSrc":"brief:0","by":{"0":"42"}},{"t":"case","label":"Pittsburgh Ry. v. Bd. of Pub. Works","cite":"172 U.S. 32","y":1898,"id":"scdb/1898-018","sc":1,"sum":"The collection of taxes assessed under the authority of a State is not to be restrained by writ of injunction from a court of tlie United States, unless it clearly appears, not only that the tax is illegal, but that the owner of the property taxed has no adequate remedy by the ordinary processes of the law, and that there are special circumstances bringing the ease within some recognized head of equity jurisdiction.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Porter v. Nussle","cite":"534 U.S. 516","y":2002,"id":"2001/00-853","sc":1,"op":2,"sum":"The Court held that the PLRA's exhaustion requirement applies to all inmate suits about prison life, whether they involve general circumstances or particular episodes, and whether they allege excessive force or some other wrong. The Court rejected Nussle's argument that Congress added the words \"prison conditions\" to exempt excessive force claims.","sumSrc":"Oyez","by":{"0":"5, 14, 35, 47","2":"5, 23"}},{"t":"case","label":"Preiser v. Rodriguez","cite":"411 U.S. 475","y":1973,"id":"1972/71-1369","sc":1,"sum":"When a state prisoner challenges the fact or duration of his physical imprisonment and by way of relief seeks a determination that he is entitled to immediate release or a speedier release, his sole federal remedy is a writ of habeas corpus.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Quackenbush v. Allstate Ins. Co.","cite":"517 U.S. 706","y":1996,"id":"1995/95-244","sc":1,"sum":"The Court held that an abstention-based remand order is appealable because the \"remand order here falls within that narrow class of collateral orders that are immediately appealable.\" Further, the Court held that the \"federal courts have the power to dismiss or remand cases based on abstention principles only where the relief sought is equitable or otherwise discretionary,\" and because \"this was a damages action, the District Court's remand order was an unwarranted application of the Burford doctrine.\" Justices Antonin Scalia and Anthony M. Kennedy wrote concurring opinions.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Rose v. Lundy","cite":"455 U.S. 509","y":1982,"id":"1981/80-846","sc":1,"sum":"The judgment is reversed and the case is remanded. 624 F. 2d 1100, reversed and remanded. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts I, II, III-A, III-B, and IV, concluding that a district court must dismiss habeas petitions containing both unexhausted and exhausted claims. A rule requiring exhaustion of all claims in state courts promotes comity and furthers the purposes underlying …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Ross v. Bernhard","cite":"396 U.S. 531","y":1970,"id":"1969/42","sc":1,"sum":"The right to trial by jury preserved by the Seventh Amendment extends to a stockholder's derivative suit with respect to those issues as to which the corporation, had it been suing in its own right, would have been entitled to a jury trial. 403 F. 2d 909, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37","1":"14, 46"}},{"t":"case","label":"Ruffin v. Commonwealth","cite":"62 Va. 790","y":1871,"url":"https://www.courtlistener.com/c/Va./62/790/","by":{"0":"21"}},{"t":"case","label":"Schlesinger v. Councilman","cite":"420 U.S. 738","y":1975,"id":"1974/73-662","sc":1,"sum":"After court-martial charges were preferred against respondent Army captain for the sale, transfer, and possession of marihuana, he brought suit in Federal District Court to enjoin petitioner military authorities from proceeding with the court-martial. The District Court granted a permanent injunction, and the Court of Appeals affirmed, on the ground that the offenses charged were not \"service connected\" and hence …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"Sinochem Int’l Co. v. Malaysia Int’l Shipping Corp.","cite":"549 U.S. 422","y":2007,"id":"2006/06-102","sc":1,"op":6,"sum":"The Court ruled 9-0 that \"a court need not resolve whether it has [...] personal jurisdiction over the defendant if it determines that [...] a foreign tribunal is plainly the more suitable arbiter of the merits of the case.\" The opinion by Justice Ruth Bader Ginsburg held that while the first step of a court is normally to determine whether it has jurisdiction, a court can dismiss a case for forum non conveniens without establishing subject-matter or personal jurisdiction.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Small v. Camden Cnty.","cite":"728 F.3d 265","y":2013,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/728/265/","op":1,"by":{"0":"16, 19","1":"22, 36"}},{"t":"case","label":"Smith v. United States","cite":"199 F.2d 377","y":1952,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/199/377/","by":{"0":"28"}},{"t":"case","label":"Smith v. World Ins. Co.","cite":"38 F.3d 1456","y":1994,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/38/1456/","by":{"0":"33"}},{"t":"case","label":"Snider v. Melindez","cite":"199 F.3d 108","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/199/108/","sum":"Explaining that exhaustion “is often a temporary, curable, procedural flaw”.","sumSrc":"brief:0","by":{"0":"19"}},{"t":"case","label":"Sprint Commc’ns, Inc. v. Jacobs","cite":"571 U.S. 69","y":2013,"id":"2013/12-815","sc":1,"sum":"The Court held that a federal court does not need to abstain from deciding a case only because there is a case in state court that deals with the same subject matter.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Sydnor v. Conseco Fin. Serv. Corp.","cite":"252 F.3d 302","y":2001,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/252/302/","by":{"0":"42"}},{"t":"case","label":"Trainor v. Hernandez","cite":"431 U.S. 434","y":1977,"id":"1976/75-1407","sc":1,"sum":"The District Court should have dismissed appellees' complaint under Younger, supra, and Huffman, supra, unless their state remedies were inadequate to litigate their federal due process claim, since the injunction asked for and issued by the court interfered with Illinois' efforts to utilize the Attachment Act as an integral part of the State's enforcement action. Pp. 440-447 (a) The principles of Younger and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Tull v. United States","cite":"481 U.S. 412","y":1987,"id":"1986/85-1259","sc":1,"op":10,"sum":"The Clean Water Act (Act) authorizes injunctive relief against violators (33 U. S. C. § 1319(b)) and subjects them to a civil penalty not to exceed $10,000 per day (§ 1319(d)). After denying petitioner's timely demand for a jury trial in the Government's suit for relief under §§ 1319(b) and 1319(d), the District Court imposed civil penalties and granted injunctive relief against petitioner. The Court of Appeals …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14, 21, 23, 27, 33, 43"}},{"t":"case","label":"United States v. Abilene & S. Ry. Co.","cite":"265 U.S. 274","y":1924,"id":"scdb/1923-159","sc":1,"sum":"1. An order made by a division of the Interstate Commerce Commission being operative, unless stayed by the division or the full Commission pending a rehearing by the latter, (amended Act to Regulate Commerce, §§ 16a, 17 [4],) a suit to enjoin enforcement of such an order is within the jurisdiction of the District Court, and whether relief should be denied until the plaintiff, through application for rehearing, shall …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"25, 29"}},{"t":"case","label":"United States v. Ill. Cent. R.R. Co.","cite":"291 U.S. 457","y":1934,"id":"scdb/1933-161","sc":1,"sum":"Assistant Solicitor General MacLean, with whom Solicitor General Biggs, Assistant Attorney General Stephens, and Messrs. Elmer B. Collins, Ashley Sellers, Daniel W. Knowlton, and Harry L. Underwood were on the brief, for the United States and Interstate Commerce Commission, appellants.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"25, 27"}},{"t":"case","label":"United States v. Sing Tuck","cite":"194 U.S. 161","y":1904,"id":"scdb/1903-137","sc":1,"sum":"It is one of the necessities of the administration of justice that all questions —even though fundamental — should be determined in an orderly way, and it is within the power of Congress to require one asserting the right to enter this country on the ground that he is acitizen, to establish his citizenship in some reasonablé way.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"23, 24, 25, 29, 41"}},{"t":"case","label":"United States v. Stauffer Chem. Co.","cite":"464 U.S. 165","y":1984,"id":"1983/82-1448","sc":1,"sum":"The Court held that the EPA's case against Stauffer was precluded by the doctrine of collateral estoppell.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Walker v. N. M. & S. P. R. Co.","cite":"165 U.S. 593","y":1897,"id":"scdb/1896-118","sc":1,"sum":"The act of April 4,1874, c. 80, legislating for all the Territories, secures to their inhabitants all the rights of trial by jury, as they existed at the common law.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"17, 18"}},{"t":"case","label":"Wal-Mart Stores, Inc. v. Dukes","cite":"564 U.S. 338","y":2011,"id":"2010/10-277","sc":1,"sum":"The Court held that the small group who initiated a lawsuit could not represent all of Wal-Mart's female employees, and therefore could not bring a class action lawsuit against Wal-Mart.","sumSrc":"Oyez","by":{"0":"17","2":"6, 7"}},{"t":"case","label":"Wetmore v. Rymer","cite":"169 U.S. 115","y":1898,"id":"scdb/1897-063","sc":1,"op":2,"ar":3,"sum":"Describing “trial[s] had with a jury” over subject-matter jurisdiction.","sumSrc":"opinion","by":{"0":"17","2":"10"}},{"t":"case","label":"Withrow v. Williams","cite":"507 U.S. 680","y":1993,"id":"1992/91-1030","sc":1,"sum":"The Supreme Court held that the decision in Stone had been one of prudence rather than one of jurisdiction.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Woodford v. Ngo","cite":"548 U.S. 81","y":2006,"id":"2005/05-416","sc":1,"op":4,"ar":2,"sum":"In a 6-to-3 decision authored by Justice Samuel Alito, the Supreme Court held that a prisoner must properly exhaust any available administrative remedies before bringing suit in federal court. This understanding of the PLRA's exhaustion provision mirrors that of the traditional exhaustion provision in administrative law and is \"substantively similar\" to that of habeas corpus law.","sumSrc":"Oyez","by":{"0":"4, 28, 32, 35, 36, 45, 47","1":"27, 28, 38, 41, 42","2":"4, 5, 15"}},{"t":"case","label":"Younger v. Harris","cite":"401 U.S. 37","y":1971,"id":"1970/2","sc":1,"sum":"In an 8-to-1 decision, the Court held that \"settled doctrines\" of federalism narrowly confined the availability of injunctive relief against state criminal prosecutions.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1915A","url":"https://www.law.cornell.edu/uscode/text/28/1915A","by":{"0":"37"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","subs":["(b)(1)(A)","(c)"],"by":{"0":"32, 32"}},{"t":"usc","label":"42 U.S.C. § 15601","url":"https://www.law.cornell.edu/uscode/text/42/15601","by":{"0":"6"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"1","2":"2"}},{"t":"usc","label":"42 U.S.C. § 1997e","url":"https://www.law.cornell.edu/uscode/text/42/1997e","subs":["(a)","(a)(1)","(a)(2)","(c)"],"stext":{"head":"§1997e. Suits by prisoners","paras":[[0,"(a) Applicability of administrative remedies"],[0,"No action shall be brought with respect to prison conditions under section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility until such administrative remedies as are available are exhausted."],[0,"(b) Failure of State to adopt or adhere to administrative grievance procedure"],[0,"The failure of a State to adopt or adhere to an administrative grievance procedure shall not constitute the basis for an action under section 1997a or 1997c of this title."],[0,"(c) Dismissal"],[0,"(1) The court shall on its own motion or on the motion of a party dismiss any action brought with respect to prison conditions under section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility if the court is satisfied that the action is frivolous, malicious, fails to state a claim upon which relief can be granted, or seeks monetary relief from a defendant who is immune from such relief."],[0,"(2) In the event that a claim is, on its face, frivolous, malicious, fails to state a claim upon which relief can be granted, or seeks monetary relief from a defendant who is immune from such relief, the court may dismiss the underlying claim without first requiring the exhaustion of administrative remedies."],[0,"(d) Attorney's fees"],[0,"(1) In any action brought by a prisoner who is confined to any jail, prison, or other correctional facility, in which attorney's fees are authorized under section 1988 1 of this title, such fees shall not be awarded, except to the extent that—"],[1,"(A) the fee was directly and reasonably incurred in proving an actual violation of the plaintiff's rights protected by a statute pursuant to which a fee may be awarded under section 1988 1 of this title; and"],[1,"(B)(i) the amount of the fee is proportionately related to the court ordered relief for the violation; or"],[1,"(ii) the fee was directly and reasonably incurred in enforcing the relief ordered for the violation."],[0,"(2) Whenever a monetary judgment is awarded in an action described in paragraph (1), a portion of the judgment (not to exceed 25 percent) shall be applied to satisfy the amount of attorney's fees awarded against the defendant. If the award of attorney's fees is not greater than 150 percent of the judgment, the excess shall be paid by the defendant."],[0,"(3) No award of attorney's fees in an action described in paragraph (1) shall be based on an hourly rate greater than 150 percent of the hourly rate established under section 3006A of title 18 for payment of court-appointed counsel."],[0,"(4) Nothing in this subsection shall prohibit a prisoner from entering into an agreement to pay an attorney's fee in an amount greater than the amount authorized under this subsection, if the fee is paid by the individual rather than by the defendant pursuant to section 1988 1 of this title."],[0,"(e) Limitation on recovery"],[0,"No Federal civil action may be brought by a prisoner confined in a jail, prison, or other correctional facility, for mental or emotional injury suffered while in custody without a prior showing of physical injury or the commission of a sexual act (as defined in section 2246 of title 18)."],[0,"(f) Hearings"],[0,"(1) To the extent practicable, in any action brought with respect to prison conditions in Federal court pursuant to section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility, pretrial proceedings in which the prisoner's participation is required or permitted shall be conducted by telephone, video conference, or other telecommunications technology without removing the prisoner from the facility in which the prisoner is confined."],[0,"(2) Subject to the agreement of the official of the Federal, State, or local unit of government with custody over the prisoner, hearings may be conducted at the facility in which the prisoner is confined. To the extent practicable, the court shall allow counsel to participate by telephone, video conference, or other communications technology in any hearing held at the facility."],[0,"(g) Waiver of reply"],[0,"(1) Any defendant may waive the right to reply to any action brought by a prisoner confined in any jail, prison, or other correctional facility under section 1983 of this title or any other Federal law. Notwithstanding any other law or rule of procedure, such waiver shall not constitute an admission of the allegations contained in the complaint. No relief shall be granted to the plaintiff unless a reply has been filed."],[0,"(2) The court may require any defendant to reply to a complaint brought under this section if it finds that the plaintiff has a reasonable opportunity to prevail on the merits."],[0,"(h) \"Prisoner\" defined"],[0,"As used in this section, the term \"prisoner\" means any person incarcerated or detained in any facility who is accused of, convicted of, sentenced for, or adjudicated delinquent for, violations of criminal law or the terms and conditions of parole, probation, pretrial release, or diversionary program."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1997e?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1997e. Suits by prisoners","tname":"The Public Health and Welfare","by":{"0":"2, 13, 4, 4","2":"4, 5, 11, 23, 4"}},{"t":"rule","label":"Fed. R. Civ. P. 39","url":"https://www.law.cornell.edu/rules/frcp/rule_39","subs":["(a)","(a)(2)"],"by":{"0":"22, 22"}},{"t":"const","label":"Amendment VII","clauses":[["seventh-amendment","Seventh Amendment (Civil Jury)"]],"text":"In Suits at common law, where the value in controversy shall exceed twenty dollars, the right of trial by jury shall be preserved, and no fact tried by a jury, shall be otherwise re-examined in any Court of the United States, than according to the rules of the common law.","by":{"0":"2, 13, 20","1":"22-24, 26, 30-32, 34, 35, 37, 43, 45, 46, 48"}},{"t":"case","label":"Alliance for Envtl. Renewal v. Pyramid Crossgates Co.","cite":"436 F.3d 82","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/436/82/","by":{"1":"19"}},{"t":"case","label":"Anniston Manufacturing Co. v. Davis","cite":"301 U.S. 337","y":1937,"id":"scdb/1936-119","sc":1,"sum":"(1) If the taxpayer has thus shifted the burden of the tax, he is no longer in a position to claim an actual injury and the refusal of a refund in such a case cannot be regarded as a denial of constitutional right. P 348. (2) The fact that the Act makes no provision for refunding to particular persons, to whom the burden of the invalid exaction may be found to have been shifted, is no concern of the taxpayer. P. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Begolli v. Home Depot U.S.A., Inc.","cite":"701 F.3d 1158","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/701/1158/","by":{"1":"35, 36"}},{"t":"case","label":"Brown v. Slenker","cite":"220 F.3d 411","y":2000,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/220/411/","by":{"1":"19"}},{"t":"case","label":"Byrd v. Blue Ridge Rural Elec. Co-op., Inc.","cite":"356 U.S. 525","y":1958,"id":"1957/57","sc":1,"op":1,"sum":"Holding that affrmative defense should go to jury due to “the manner in which [the federal system] distributes trial functions between judge and jury,” making it “unnecessary” to consider “the constitutional question”.","sumSrc":"opinion","by":{"1":"34-35"}},{"t":"case","label":"Page(s) Curtis v. Loether","cite":"415 U.S. 189","y":1974,"id":"1973/72-1035","sc":1,"sum":"The Seventh Amendment of the Constitution entitles either party to demand a jury trial in an action for damages in the federal courts under § 812 of the Civil Rights Act of 1968, which authorizes privateplaintiffs to bring civil actions to redress violations of the Act's fair housing provisions. Pp. 191-198. 467 F. 2d 1110, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25, 31"}},{"t":"case","label":"Daum v. Doe","cite":"2016 WL 3411558","y":2016,"court":"W.D.N.Y. June 22","by":{"1":"23"}},{"t":"case","label":"Dobson v. Pearce","cite":"12 N.Y. 156","y":1854,"url":"https://www.courtlistener.com/c/N.Y./12/156/","by":{"1":"46"}},{"t":"case","label":"First National Bank v. Board of County Commissioners","cite":"264 U.S. 450","y":1924,"id":"scdb/1923-109","sc":1,"sum":"An action by a national bank to recover the amount of taxes levied by a State and paid under protest, upon the ground that they were excessive, discriminatory and violative of Rev. Stats., § 5219, held not maintainable in the District Court, where the plaintiff failed to avail itself of an administrative remedy afforded by the state law as conclusively established by a decision of the State Supreme Court.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Fowler v. Land Mgmt. Groupe, Inc.","cite":"978 F.2d 158","y":1992,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/978/158/","by":{"1":"34"}},{"t":"case","label":"Google LLC v. Oracle Am. Inc.","cite":"593 U.S. 1","y":2021,"id":"2020/18-956","sc":1,"sum":"Google’s limited copying of the Java SE Application Programming Interface allowed programmers to put their accrued talents to work in a transformative program and constituted a fair use of that material under copyright law.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"33, 34, 42","2":"20"}},{"t":"case","label":"Grand Lodge Bhd. Of R.R. Trainmen v. Randolph","cite":"57 N.E. 882","y":1900,"url":"https://www.courtlistener.com/c/N.E./57/882/","by":{"1":"39"}},{"t":"case","label":"Gunn v. Ayala","cite":"2023 WL 2664342","y":2023,"court":"S.D.N.Y. Mar. 28","by":{"1":"23"}},{"t":"case","label":"Holmberg v. Armbrecht","cite":"327 U.S. 392","y":1946,"id":"scdb/1945-049","sc":1,"sum":"1. Decision of a suit in a federal court to enforce a federally created equitable right is not controlled by the statute of limitations of the State of the forum. Guaranty Trust Co. v. York, 326 U. S. 99, distinguished. Accordingly, a class suit by creditors of a joint stock land bank to enforce the liability imposed upon shareholders of the bank by § 16 of the Federal Farm Loan Act is not barred by the state …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"Jones v. Bock","cite":"549 U.S. 199","y":2007,"id":"2006/05-7058","sc":1,"op":8,"ar":2,"sum":"The Court ruled unanimously that the Sixth Circuit's rules for exhaustion of administrative remedies were not required by the Prisoner Litigation Reform Act. The opinion by Chief Justice John Roberts held that prisoners bring civil rights lawsuits do not need to demonstrate that they have already exhausted all administrative remedies.","sumSrc":"Oyez","by":{"1":"27-29, 31, 35-39, 41, 43, 48","2":"5"}},{"t":"case","label":"Katz v. Goodyear Tire Rubber Co.","cite":"737 F.2d 238","y":1984,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/737/238/","by":{"1":"34"}},{"t":"case","label":"Page(s) Land v. Dollar","cite":"330 U.S. 731","y":1947,"id":"scdb/1946-082","sc":1,"op":3,"sum":"The district court had jurisdiction to determine its jurisdiction by proceeding to a decision on the merits.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3, 18, 19","2":"10"}},{"t":"case","label":"Lytle v. Household Mfg., Inc.","cite":"494 U.S. 545","y":1990,"id":"1989/88-334","sc":1,"ar":2,"sum":"Petitioner Lytle, an Afro-American, filed an action under both Title VII of the Civil Rights Act of 1964 and 42 U. S. C. § 1981, alleging that respondent Schwitzer Turbochargers had terminated his employment because of his race and had retaliated against him for filing a charge with the Equal Employment Opportunity Commission by subsequently providing inadequate references to prospective employers. He requested a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3, 14, 25-27, 31","2":"12"}},{"t":"case","label":"Maraglia v. Maloney","cite":"499 F. Supp. 2d 93","y":2007,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/499/93/","by":{"1":"38"}},{"t":"case","label":"Pavey v. Conley","cite":"544 F.3d 730","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/544/730/","op":2,"by":{"1":"26, 36, 38"}},{"t":"case","label":"Petrella v. Metro-Goldwyn-Mayer, Inc.","cite":"572 U.S. 663","y":2014,"id":"2013/12-1315","sc":1,"sum":"The Court held that the doctrine of laches could not be used to prevent a copyright suit that seeks relief for damages that occurred within the three-year window allowed by the Copyright Act.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Reid v. Covert","cite":"354 U.S. 1","y":1957,"id":"1955/701","sc":1,"sum":"Citizen spouses of members of the U.S. military abroad are not subject to the U.S. Code of Military Justice but are entitled to Fifth and Sixth Amendment protections","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Ross v. Blake","cite":"578 U.S. 632","y":2016,"id":"2015/15-339","sc":1,"op":2,"ar":2,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"1":"7, 13, 41, 42","2":"11, 23"}},{"t":"case","label":"Sanchez v. Nassau County","cite":"662 F. Supp. 3d 369","y":2023,"court":"E.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/662/369/","by":{"1":"23"}},{"t":"case","label":"SCA Hygiene Products Aktiebolag v. First Quality Baby Products, LLC","cite":"580 U.S. 328","y":2017,"id":"2016/15-927","sc":1,"sum":"The Court determined that an unreasonable delay in litigation cannot bar claims for patent infringement that are brought within the six-year statutory period of limitations.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"SEC v. Jarkesy","cite":"144 S. Ct. 2117","y":2024,"id":"2023/22-859","sc":1,"op":1,"ar":3,"sum":"When the Securities and Exchange Commission seeks civil penalties against a defendant for securities fraud, the Seventh Amendment entitles the defendant to a jury trial.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"1, 14, 30, 34"}},{"t":"case","label":"Smithers v. Smith","cite":"204 U.S. 632","y":1907,"id":"scdb/1906-099","sc":1,"op":8,"ar":2,"sum":"When the Circuit Court dismisses a case under the. provisions of § 1 of the act of March 3, 1875, 18 Stat. 470, as amended by § 1 of the act of August 13, 1888, 25 Stat. 434, because not substantially involving the requisite amount in controversy to confer jurisdiction*, the order of the court, in this case without a jury, is subject to review in this court in respect to the rulings of law and findings of fact upon …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18","2":"12"}},{"t":"case","label":"Stanley v. Supervisors of Albany","cite":"121 U.S. 535","y":1887,"id":"scdb/1886-241","sc":1,"sum":"When the case below is tried by a court without a jury, its findings upon questions of fact are conclusive; and. this court can consider only its rulings on matters of law properly presented in a bill of exceptions, and the further question, when the findings are special, whether the facts found are sufficient to sustain the judgment rendered.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Starbucks Corporation v. McKinney","cite":"602 U.S. 339","y":2024,"id":"2023/23-367","sc":1,"sum":"When considering the National Labor Relations Board’s request for a preliminary injunction under §10( j) of the National Labor Relations Act, district courts must apply the traditional four factors articulated in Winter v. Natural Resources Defense Council, Inc., 555 U. S. 7 (2008).","sumSrc":"Holding (supremecourt.gov)","by":{"1":"41"}},{"t":"case","label":"Stephens v. Venetozzi","cite":"2020 WL 7629124","y":2020,"court":"S.D.N.Y. Dec. 21","by":{"1":"23"}},{"t":"case","label":"Teamsters v. Terry","cite":"494 U.S. 558","y":1990,"id":"1989/88-1719","sc":1,"sum":"The judgment is affirmed. 863 F. 2d 334, affirmed. JUSTICE MARSHALL delivered the opinion of the Court with respect to Parts 1, 11, III-B, and IV, concluding that the Seventh Amendment entitles respondents to a jury trial. Pp. 563-564, 570-574.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14, 40"}},{"t":"case","label":"U.S. Bank Nat’l Ass’n v. Village at Lakeridge, LLC","cite":"583 U.S. 387","y":2018,"id":"2017/15-1509","sc":1,"sum":"The Court held that a designation of non-statutory insider status is reviewable under the standard of clear error because the \"mixed question\" of law and fact at issue is primarily factual.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Vance v. Ball State","cite":"570 U.S. 421","y":2013,"id":"2012/11-556","sc":1,"sum":"The Court held that, for purposes of liability for workplace harassment, the definition of \"supervisor\" is limited to a person empowered to take tangible employment action against the victim.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Williams v. Runyon","cite":"130 F.3d 568","y":1997,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/130/568/","by":{"1":"35"}},{"t":"case","label":"Zipes v. TransWorld Airlines, Inc.","cite":"455 U.S. 385","y":1982,"id":"1981/78-1545","sc":1,"sum":"In 1970, the union then representing flight attendants employed by respondent Trans World Airlines, Inc. (TWA), brought a federal-court class action alleging that TWA practiced unlawful sex discrimination in violation of Title VII of the Civil Rights Act of 1964 by its policy of grounding all female flight attendants who became mothers while their male counterparts who became fathers were permitted to continue …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"1":"1, 4, 6, 7, 12"}},{"t":"usc","label":"28 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/28/1983","by":{"1":"9, 17, 23, 31-33, 40, 43, 48"}},{"t":"usc","label":"28 U.S.C. § 298","url":"https://www.law.cornell.edu/uscode/text/28/298","subs":["(1915)"],"by":{"1":"45"}},{"t":"usc","label":"28 U.S.C. § 1602","url":"https://www.law.cornell.edu/uscode/text/28/1602","by":{"1":"16"}},{"t":"rule","label":"Fed. R. Civ. P. 8","url":"https://www.law.cornell.edu/rules/frcp/rule_8","subs":["(c)(1)"],"by":{"1":"40"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(b)","(b)(6)"],"by":{"1":"16, 16","2":"5, 7"}},{"t":"rule","label":"Fed. R. Civ. P. 56","url":"https://www.law.cornell.edu/rules/frcp/rule_56","by":{"1":"39"}},{"t":"rule","label":"Fed. R. Civ. P. 65","url":"https://www.law.cornell.edu/rules/frcp/rule_65","by":{"1":"24"}},{"t":"case","label":"Amgen Inc. v. Conn. Ret. Plans & Tr. Funds","cite":"568 U.S. 455","y":2013,"id":"2012/11-1085","sc":1,"sum":"The Court held that during class certification, the court does not need proof of materiality and does not have to allow the defendant to present evidence to rebut the certification.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"case","label":"Bargher v. White","cite":"928 F.3d 439","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/928/439/","by":{"2":"11"}},{"t":"case","label":"Battle v. Ledford","cite":"912 F.3d 708","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/912/708/","by":{"2":"16"}},{"t":"case","label":"Berry v. Kerik","cite":"366 F.3d 85","y":2004,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/366/85/","by":{"2":"11"}},{"t":"case","label":"Boyd v. Corr. Corp. of Am.","cite":"380 F.3d 989","y":2004,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/380/989/","by":{"2":"11"}},{"t":"case","label":"Ford v. Johnson","cite":"362 F.3d 395","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/362/395/","by":{"2":"11"}},{"t":"case","label":"Gallagher v. Shelton","cite":"587 F.3d 1063","y":2009,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/587/1063/","by":{"2":"11"}},{"t":"case","label":"Gariety v. Grant Thornton, LLP","cite":"368 F.3d 356","y":2004,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/368/356/","sum":"Noting that inquiry as to Rule 23 prerequisites would not bind “the ultimate factfinder’s finding on the merits” of the underlying issues any more than does a finding that the plaintiff has shown a probability of success for purposes of a preliminary injunction.","sumSrc":"brief:2","by":{"2":"17"}},{"t":"case","label":"Garrett v. Wexford Health","cite":"938 F.3d 69","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/938/69/","by":{"2":"11"}},{"t":"case","label":"Gen. Tel. Co. of Sw. v. Falcon","cite":"457 U.S. 147","y":1982,"id":"1981/81-574","sc":1,"sum":"The District Court erred in permitting respondent to maintain a class action on behalf of both employees who were denied promotion and applicants who were denied employment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"7"}},{"t":"case","label":"Gulf Oil Corp. v. Copp Paving Co.","cite":"419 U.S. 186","y":1974,"id":"1974/73-1012","sc":1,"op":2,"sum":"Respondent operators of a California \"hot plant,\" at which asphaltic concrete for surfacing highways is manufactured and sold entirely intrastate, alleging violations of, inter alia, § 2 (a) of the Clayton Act, as amended by the Robinson-Patman Act (hereafter § 2 (a)), and §§ 3 and 7 of the Clayton Act, brought suit against petitioner liquid asphalt producers and two of their subsidiaries, to which such asphalt is …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"10"}},{"t":"case","label":"McKinney v. Carey","cite":"311 F.3d 1198","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/311/1198/","by":{"2":"11"}},{"t":"case","label":"Moss v. Harwood","cite":"19 F.4th 614","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/19/614/","by":{"2":"11"}},{"t":"case","label":"Porter v. Sturm","cite":"781 F.3d 448","y":2015,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/781/448/","by":{"2":"11"}},{"t":"case","label":"Savage v. United States Dep’t of Just.","cite":"91 F.4th 480","y":2024,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/91/480/","by":{"2":"11"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"op":3,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"2":"9"}},{"t":"case","label":"Tellabs, Inc. v. Makor Issues & Rights, Ltd.","cite":"551 U.S. 308","y":2007,"id":"2006/06-484","sc":1,"ar":1,"sum":"The Court ruled by a vote of 8-1 that a securities fraud complaint must allege facts establishing an inference of guilty intent that is \"cogent and at least as compelling as any opposing inference of nonfraudulent intent.\" Justice Ruth Bader Ginsburg wrote that opinion for the Court, which held that the Seventh Circuit's more relaxed standard was not strong enough to comport with Congress's intent in PSLRA to limit securities fraud litigation. \"The strength of an inference cannot be decided in a vacuum.","sumSrc":"Oyez","by":{"2":"7, 8"}},{"t":"case","label":"Teva Pharms. USA, Inc. v. Sandoz, Inc.","cite":"574 U.S. 318","y":2015,"id":"2014/13-854","sc":1,"sum":"The Court ruled that a federal appellate court can only overturn a district court’s finding of fact if those findings were determined to be “clearly erroneous.”","sumSrc":"Oyez","by":{"2":"9"}},{"t":"case","label":"Urfirer v. Cornfeld","cite":"408 F.3d 710","y":2005,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/408/710/","by":{"2":"17"}},{"t":"case","label":"Varner v. Shepard","cite":"11 F.4th 1252","y":2021,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/11/1252/","op":1,"by":{"2":"11"}},{"t":"case","label":"Young v. United States","cite":"535 U.S. 43","y":2002,"id":"2001/00-1567","sc":1,"sum":"The Court held section 507(a)(8)(A)(i)'s lookback period is tolled during the pendency of a prior bankruptcy petition. The Court reasoned that the three-year lookback period is a limitations period subject to traditional principles of equitable tolling and that nothing in the Bankruptcy Code precluded the equitable tolling of the lookback period.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"law","label":"Pub. L. No. 96-247","by":{"2":"4"}},{"t":"reg","label":"28 C.F.R. § 115.52","url":"https://www.ecfr.gov/current/title-28/section-115.52","subs":["(b)(1)"],"by":{"2":"14"}},{"t":"rule","label":"Fed. R. Civ. P. 23","url":"https://www.law.cornell.edu/rules/frcp/rule_23","by":{"2":"7"}}]};